1: """Brief week rule: weekends look ahead to next Monday, weekdays use this Monday."""
2: 
3: import from datetime { date, datetime }
4: 
5: test "weekend briefs are for the next Monday" {
6:     assert brief_monday(date(2026, 9, 26)) == date(2026, 9, 28);   # Saturday
7:     assert brief_monday(date(2026, 9, 27)) == date(2026, 9, 28);   # Sunday
8: }
9: 
10: test "weekday briefs are for this week's Monday" {
11:     assert brief_monday(date(2026, 9, 28)) == date(2026, 9, 28);   # Monday
12:     assert brief_monday(date(2026, 9, 30)) == date(2026, 9, 28);   # Wednesday
13:     assert brief_monday(date(2026, 10, 2)) == date(2026, 9, 28);   # Friday
14:     assert brief_monday(datetime(2026, 9, 26, 23, 59)) == date(2026, 9, 28);
15: }
16: 
17: test "day index counts from the brief Monday" {
18:     assert brief_day_index(date(2026, 9, 26)) == -2;
19:     assert brief_day_index(date(2026, 9, 27)) == -1;
20:     assert brief_day_index(date(2026, 9, 28)) == 0;
21:     assert brief_day_index(date(2026, 9, 30)) == 2;
22: }
23: 
24: test "week label" {
25:     assert brief_week_label(date(2026, 9, 26)) == "Monday, September 28, 2026";
26: }

1: """Editor stage tests. The LLM path runs against byLLM's MockLLM (no key, no network)."""
2: 
3: import re;
4: import time;
5: import from datetime { date }
6: import from jaclang.byllm.lib { MockLLM, MockError }
7: import from services { pulse_llm }
8: import from services.speakable { speakable, word_count }
9: 
10: glob TODAY: date = date(2026, 9, 28);
11: glob FORBIDDEN: str = r"\b(Rd|St|Ave|Blvd|Dr|Hwy|Pkwy|Mon|Tue|Wed|Thu|Fri|Sat|Sun|AM|PM|U-M)\b|\b[NSEW]\b|[&@$%()*#]|https?:";
12: 
13: # Deliberately un-speakable: abbreviations, symbols, markdown, emoji, a URL and parentheses.
14: glob RAW_LLM: str = "**Morning Jordan!** 🚲 Plymouth Rd is down to one lane Wed to Fri (7 AM to 5 PM), right on your U-M bike route, so leave 10 min early or use the Fuller Rd path. North Campus Pizza & Game Night is Sat 7:00 PM at Pierpont, free, and close to home. The Plymouth Rd bike lane hearing is Wed 6:30 PM; sign up to comment at https://a2gov.legistar.com. The Bursley-Baits bus skips Pierpont Sat afternoon, so give yourself extra time. Free Jazz Night at Blue LLama on S Main St is Fri 8:00 PM, walk-ins welcome. That's your week!";
15: 
16: glob ITEMS: list[dict[str, any]] = [
17:     {"name": "Plymouth Rd lane closure", "kind": "alert", "when": "Wed to Fri, 7 AM to 5 PM", "reasons": ["Near your home in North Campus", "On your bike route via Plymouth Rd corridor"], "action": "Leave 10 minutes early or take the Fuller Rd path instead."},
18:     {"name": "North Campus Pizza & Game Night", "kind": "event", "when": "Sat 7:00 PM", "reasons": ["Close by at Pierpont Commons", "Matches your interest in social"], "action": "Free. Save it to your calendar for Sat 7:00 PM."},
19:     {"name": "Plymouth Rd protected bike lane plan", "kind": "civic", "when": "Wed 6:30 PM hearing", "reasons": ["Affects North Campus, where you live or travel"], "action": "Sign up for public comment or email Council: Wed 6:30 PM hearing."},
20:     {"name": "Bursley-Baits bus reroute", "kind": "alert", "when": "Sat afternoon", "reasons": ["Near your home in North Campus"], "action": "Check TheRide trip planner and give yourself 10 extra minutes."},
21:     {"name": "Free Jazz Night", "kind": "event", "when": "Fri 8:00 PM", "reasons": ["Matches your interest in music", "From U-M Jazz Collective, which you follow"], "action": "RSVP and grab a ticket ($5) for Fri 8:00 PM."}
22: ];
23: 
24: def mock(outputs: list[any]) {
25:     pulse_llm.set_llm(MockLLM(model_name="mockllm", config={"outputs": outputs}), "mockllm");
26: }
27: 
28: test "llm output goes through speakable" {
29:     mock([RAW_LLM]);
30:     out = edit_brief("Jordan", "Jordan, U-M junior", ITEMS, True, TODAY);
31:     pulse_llm.set_llm(None);
32:     assert out["mode"] == "llm", out["error"];
33:     assert out["model"] == "mockllm";
34:     assert out["raw_llm"] == RAW_LLM;
35:     assert out["spoken"] == speakable(RAW_LLM, TODAY);
36:     assert re.search(FORBIDDEN, out["spoken"]) is None, out["spoken"];
37:     assert "Plymouth Road" in str(out["spoken"]);
38:     assert "Saturday at 7 p.m." in str(out["spoken"]);
39:     assert "University of Michigan" in str(out["spoken"]);
40:     # The LLM sees speakable item text, so it never guesses at abbreviations.
41:     assert "1. Plymouth Road lane closure" in str(out["input"]["items"]);
42:     assert "Wednesday to Friday, 7 a.m. to 5 p.m." in str(out["input"]["items"]);
43: }
44: 
45: test "llm error falls back to the template" {
46:     mock([MockError(error=RuntimeError("provider down"))]);
47:     out = edit_brief("Jordan", "Jordan", ITEMS, True, TODAY);
48:     pulse_llm.set_llm(None);
49:     assert out["mode"] == "template";
50:     assert "provider down" in str(out["error"]);
51:     assert out["raw_llm"] is None;
52:     assert out["spoken"].startswith("Good morning, Jordan.");
53: }
54: 
55: test "too-short llm output falls back to the template" {
56:     mock(["Have a good week."]);
57:     out = edit_brief("Jordan", "Jordan", ITEMS, True, TODAY);
58:     pulse_llm.set_llm(None);
59:     assert out["mode"] == "template";
60:     assert "too short" in str(out["error"]);
61:     assert out["raw_llm"] == "Have a good week.";
62: }
63: 
64: test "llm off uses the template with no waiting" {
65:     pulse_llm.set_llm(None);
66:     t0 = time.perf_counter();
67:     out = edit_brief("Jordan", "Jordan", ITEMS, True, TODAY);
68:     elapsed = time.perf_counter() - t0;
69:     assert out["mode"] == "template";
70:     assert out["error"] == "LLM off";
71:     assert elapsed < 0.5, elapsed;
72: }
73: 
74: test "template is 130 to 180 speakable words" {
75:     out = template_brief("Jordan", ITEMS, TODAY);
76:     assert 130 <= word_count(out) <= 180, f"{word_count(out)}: {out}";
77:     assert re.search(FORBIDDEN, out) is None, out;
78:     assert speakable(out, TODAY) == out;
79:     assert "5 dollars" in out;
80: }
81: 
82: test "template handles a quiet week and the You persona" {
83:     assert template_brief("You", [], TODAY).startswith("Good morning. It's a quiet week");
84:     one = template_brief("You", ITEMS[:1], TODAY);
85:     assert one.startswith("Good morning. It's a pretty easy week, with one thing to plan around."), one;
86: }
87: 
88: test "deadline abandons a slow call" {
89:     def slow -> str {
90:         time.sleep(2.0);
91:         return "late";
92:     }
93:     res = pulse_llm.call_with_deadline(slow, [], 0.3);
94:     assert not res["ok"];
95:     assert "timed out" in res["error"];
96:     assert res["ms"] < 1000, res["ms"];
97: }
98: 
99: test "deadline returns values and errors" {
100:     ok = pulse_llm.call_with_deadline(lambda (a: int, b: int) -> int { return a + b; }, [2, 3], 1.0);
101:     assert ok["ok"] and ok["value"] == 5;
102:     def boom -> str {
103:         raise ValueError("bad");
104:     }
105:     bad = pulse_llm.call_with_deadline(boom, [], 1.0);
106:     assert not bad["ok"] and "ValueError: bad" in bad["error"];
107: }
108: 
109: test "provider detection" {
110:     assert pulse_llm.llm_provider("gpt-4o-mini") == "openai";
111:     assert pulse_llm.llm_provider("claude-haiku-4-5") == "anthropic";
112:     assert pulse_llm.llm_provider("gemini/gemini-2.0-flash") == "gemini";
113:     assert pulse_llm.llm_provider("ollama/llama3.1") == "ollama";
114:     assert pulse_llm.llm_provider("mystery-model") == "";
115: }
116: 
117: test "template never trims the time of an alert or civic item" {
118:     long_items: list[dict[str, any]] = [
119:         {**it, "reasons": list(it["reasons"]) + ["Coming up in the next 2 days", "From City of Ann Arbor, which you follow"]}
120:         for it in ITEMS
121:     ];
122:     out = template_brief("Jordan", long_items, TODAY);
123:     assert word_count(out) <= 180, word_count(out);
124:     for it in long_items {
125:         if str(it["when"]) not in str(it["action"]) {
126:             assert speakable(str(it["when"]), TODAY) in out, f"{it['when']} missing from: {out}";
127:         }
128:     }
129:     assert "Wednesday to Friday, 7 a.m. to 5 p.m." in out;
130:     assert "Saturday afternoon" in out;
131: }
132: 
133: test "reasons are ordered strongest first" {
134:     rules: list[dict[str, any]] = [
135:         {"rule": "interest", "points": 1.5, "detail": "Matches your interest in music"},
136:         {"rule": "follows", "points": 2.0, "detail": "From U-M Jazz Collective, which you follow"},
137:         {"rule": "near_venue", "points": 1.0, "detail": "Close by at The Ark"},
138:         {"rule": "near_venue", "points": 1.0, "detail": "Close by at The Ark"}
139:     ];
140:     got = strongest_first(["Matches your interest in music", "Close by at The Ark", "From U-M Jazz Collective, which you follow"], rules);
141:     # The double-counted "Close by" counts once, so it does not tie with the follow.
142:     assert got == ["From U-M Jazz Collective, which you follow", "Matches your interest in music", "Close by at The Ark"], got;
143: }
144: 
145: test "narrative template: alert phrasing, no labels" {
146:     one: list[dict[str, any]] = [{"name": "State St sidewalk closure", "kind": "alert", "when": "All week", "reasons": ["From City of Ann Arbor, which you follow"], "action": "Use the east side crossing."}];
147:     out = template_brief("Luis", one, TODAY);
148:     assert "the State Street sidewalk closure runs all week" in out, out;
149:     assert "Why it matters" not in out and "First," not in out, out;
150: }
151: 
152: test "the Editor is told the Monday the brief is for (next Monday on weekends)" {
153:     mock(["Good morning Jordan. " + " ".join(["word"] * 120)]);
154:     out = edit_brief("Jordan", "Jordan", ITEMS, True, date(2026, 9, 26));
155:     pulse_llm.set_llm(None);
156:     assert out["input"]["week_of"] == "Monday, September 28, 2026", out["input"];
157:     assert "today" not in dict(out["input"]);
158:     sunday = edit_brief("Jordan", "Jordan", ITEMS, False, date(2026, 9, 27));
159:     assert sunday["input"]["week_of"] == "Monday, September 28, 2026";
160:     monday = edit_brief("Jordan", "Jordan", ITEMS, False, date(2026, 9, 28));
161:     assert monday["input"]["week_of"] == "Monday, September 28, 2026";
162: }
163: 
164: test "an LLM brief over 180 words falls back to the template" {
165:     long = "Good morning Jordan. " + " ".join(["Plymouth Road is busy this week."] * 40);
166:     mock([long]);
167:     out = edit_brief("Jordan", "Jordan", ITEMS, True, TODAY);
168:     pulse_llm.set_llm(None);
169:     assert out["mode"] == "template";
170:     assert "too long" in str(out["error"]), out["error"];
171:     assert out["raw_llm"] == long;
172:     assert out["spoken"].startswith("Good morning, Jordan.") and out["words"] <= 180;
173: }
174: 
175: test "an LLM brief that says today, tonight or tomorrow falls back to the template" {
176:     for word in ["today", "Tonight", "tomorrow"] {
177:         text = "Good morning Jordan. The council votes " + word + " at 7 p.m. " + " ".join(["Plymouth Road work runs all week."] * 12);
178:         mock([text]);
179:         out = edit_brief("Jordan", "Jordan", ITEMS, True, TODAY);
180:         pulse_llm.set_llm(None);
181:         assert out["mode"] == "template", word;
182:         assert word in str(out["error"]), out["error"];
183:     }
184: }
185: 
186: test "acronyms reach the LLM already expanded" {
187:     items: list[dict[str, any]] = [{"name": "UMS Symphony: Rachmaninoff 2", "kind": "event", "when": "Sun 4:00 PM", "reasons": ["From UMS, which you follow"], "action": "RSVP and grab a ticket ($12) for Sun 4:00 PM."}];
188:     text = editor_items_text(items, TODAY);
189:     assert "University Musical Society Symphony: Rachmaninoff 2" in text, text;
190:     assert "12 dollars" in text and "Sunday at 4 p.m." in text and "UMS" not in text, text;
191: }
192: 
193: test "an LLM brief that copies the style example falls back to the template" {
194:     copied = "Good morning Jordan. It's a pretty easy week. " + " ".join(["Plymouth Road is down to one lane."] * 10) + " Friday night, SCOR has a homecoming pregame at ten. Have a good week.";
195:     mock([copied]);
196:     out = edit_brief("Jordan", "Jordan", ITEMS, True, TODAY);
197:     pulse_llm.set_llm(None);
198:     assert out["mode"] == "template";
199:     assert "style example" in str(out["error"]), out["error"];
200: }
201: 
202: test "the LLM sees items grouped: getting around, worth your time, civic" {
203:     text = editor_items_text(ITEMS, TODAY);
204:     assert text.index("Getting around:") < text.index("Worth your time:") < text.index("Civic:"), text;
205: }
206: 
207: test "an LLM brief that repeats a reason phrase falls back to the template" {
208:     text = "Good morning Jordan. It's a busy week. The Plymouth Road closure runs Wednesday to Friday, near your home in North Campus. " + " ".join(["Plymouth Road work continues all week."] * 8) + " The bus reroute is Saturday afternoon, near your home too. Have a good week.";
209:     mock([text]);
210:     out = edit_brief("Jordan", "Jordan", ITEMS, True, TODAY);
211:     pulse_llm.set_llm(None);
212:     assert out["mode"] == "template";
213:     assert "repeats a reason phrase" in str(out["error"]) and "near your home" in str(out["error"]), out["error"];
214:     assert repeated_reason("since you follow A. since you follow B.") == "since you follow";
215:     assert repeated_reason("since you follow A, from B, who you follow.") == "";
216: }

