{"file_path": "/workspace/services/brief_dates.jac", "content": """"Brief week rule: weekends look ahead to next Monday, weekdays use this Monday."""

import from datetime { date, datetime, timedelta }

"""Normalize a date or datetime to a plain date."""
def _as_date(day: date) -> date {
    if isinstance(day, datetime) {
        return day.date();
    }
    return day;
}

"""The Monday a brief generated on `day` is for: next Monday on Saturday or Sunday, otherwise this week's Monday."""
def brief_monday(day: date) -> date {
    d = _as_date(day);
    wd = d.weekday();
    if wd >= 5 {
        return d + timedelta(days=7 - wd);
    }
    return d - timedelta(days=wd);
}

"""Days from the brief Monday to `day` (negative on the weekend before it)."""
def brief_day_index(day: date) -> int {
    d = _as_date(day);
    return (d - brief_monday(d)).days;
}

"""Long-form label for the brief Monday, e.g. 'Monday, September 28, 2026'."""
def brief_week_label(day: date) -> str {
    m = brief_monday(day);
    return f"{m.strftime('%A')}, {m.strftime('%B')} {m.day}, {m.year}";
}
"}

