{"file_path": "/workspace/services/brief_dates.jac", "content": """"Brief week rule: weekends look ahead to next Monday, weekdays use this Monday."""

import from datetime { date, datetime, timedelta }

"""Normalize a date or datetime to a plain date."""
def _as_date(day: date) -> date {
    if isinstance(day, datetime) {
        return day.date();
    }
    return day;
}

"""The Monday a brief generated on the given day is for: next Monday on Saturday or Sunday, otherwise this week's Monday."""
def brief_monday(day: date) -> date {
    d = _as_date(day);
    wd = d.weekday();
    if wd >= 5 {
        return d + timedelta(days=7 - wd);
    }
    return d - timedelta(days=wd);
}

"""Days from the brief Monday to the given day (negative on the weekend before it)."""
def brief_day_index(day: date) -> int {
    d = _as_date(day);
    return (d - brief_monday(d)).days;
}

"""Long-form label for the brief Monday, e.g. 'Monday, September 28, 2026'."""
def brief_week_label(day: date) -> str {
    m = brief_monday(day);
    return f"{m.strftime('%A')}, {m.strftime('%B')} {m.day}, {m.year}";
}
"}

messages.content:
1: """speakable(text): deterministic rewrite of anything sent to text-to-speech.
2: 
3: Expands abbreviations (road suffixes, directions, days, months, U-M), turns
4: symbols into words, reads times as "7 p.m." and dates as "Tuesday, September
5: 29th", and strips URLs, emoji, markdown and parentheses. Idempotent, so it is
6: safe to apply to LLM output, template output, and again right before TTS.
7: 
8: Ambiguous cases: "St." / "Dr." after a street name (a capitalized word or a
9: number) are Street / Drive; before a capitalized name otherwise they are
10: Saint / Doctor ("St. Joseph" -> "Saint Joseph", "Dr. Lee" -> "Doctor Lee").
11: """
12: 
13: import re;
14: import from datetime { date }
15: 
16: glob WEEKDAYS: list[str] = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
17: glob MONTH_NAMES: list[str] = [
18:     "January", "February", "March", "April", "May", "June", "July", "August",
19:     "September", "October", "November", "December"
20: ];
21: glob DAY_ABBR: dict[str, str] = {
22:     "Mon": "Monday", "Tue": "Tuesday", "Tues": "Tuesday", "Wed": "Wednesday",
23:     "Thu": "Thursday", "Thur": "Thursday", "Thurs": "Thursday", "Fri": "Friday",
24:     "Sat": "Saturday", "Sun": "Sunday"
25: };
26: glob MONTH_ABBR: dict[str, str] = {
27:     "Jan": "January", "Feb": "February", "Mar": "March", "Apr": "April", "Jun": "June",
28:     "Jul": "July", "Aug": "August", "Sep": "September", "Sept": "September",
29:     "Oct": "October", "Nov": "November", "Dec": "December"
30: };
31: # Unambiguous road suffixes (title-case, whole word).
32: glob ROAD_ALWAYS: dict[str, str] = {
33:     "Rd": "Road", "Ave": "Avenue", "Av": "Avenue", "Blvd": "Boulevard", "Hwy": "Highway",
34:     "Pkwy": "Parkway", "Fwy": "Freeway", "Expy": "Expressway"
35: };
36: # Road suffixes that collide with other words: only expanded right after a street name.
37: glob ROAD_AFTER_NAME: dict[str, str] = {
38:     "Ln": "Lane", "Ct": "Court", "Cir": "Circle", "Ter": "Terrace", "Pl": "Place",
39:     "Sq": "Square", "Trl": "Trail"
40: };
41: glob DIRECTIONS: dict[str, str] = {
42:     "N": "North", "S": "South", "E": "East", "W": "West",
43:     "NE": "Northeast", "NW": "Northwest", "SE": "Southeast", "SW": "Southwest"
44: };
45: # Capitalized words that are not street names, so "Meet Dr. Lee" stays Doctor.
46: glob NOT_STREET: list[str] = [
47:     "meet", "with", "ask", "join", "call", "email", "see", "hear", "thank", "thanks",
48:     "from", "by", "and", "or", "the", "a", "an", "our", "your", "my", "his", "her",
49:     "their", "professor", "dean", "says", "said", "featuring", "visit", "near", "at",
50:     "to", "on", "in", "for", "via", "off", "hosted", "welcome", "hi", "hello", "dear",
51:     "including", "plus", "then", "also", "both", "good", "morning", "today", "tonight",
52:     "tomorrow", "this", "next", "last", "every", "saint", "doctor", "is", "was", "if",
53:     "monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday",
54:     "january", "february", "march", "april", "may", "june", "july", "august",
55:     "september", "october", "november", "december"
56: ];
57: # Whole-phrase expansions, applied in order (regex, replacement).
58: glob PHRASES: list[list[str]] = [
59:     [r"\bU-M\b", "University of Michigan"],
60:     [r"\bU of M\b", "University of Michigan"],
61:     [r"\bUofM\b", "University of Michigan"],
62:     [r"\bUMich\b", "University of Michigan"],
63:     [r"\bAADL\b", "Ann Arbor District Library"],
64:     [r"\bDDA\b", "Downtown Development Authority"],
65:     [r"\bUMS\b", "University Musical Society"],
66:     [r"\bSEAS\b", "School for Environment and Sustainability"],
67:     [r"\bA2\b", "Ann Arbor"],
68:     [r"\bTheRide\b", "The Ride"],
69:     [r"\bLLama\b", "Llama"],
70:     [r",\s*MI\b", ", Michigan"],
71:     [r"\be\.g\.,?", "for example"],
72:     [r"\bi\.e\.,?", "that is"],
73:     [r"\betc\.", "and so on"],
74:     [r"\bvs\.?(?=\s)", "versus"],
75:     [r"\bapprox\.?(?=\s)", "about"],
76:     [r"\bw/(?=\s)", "with"],
77:     [r"\band/or\b", "or"],
78:     [r"\b24/7\b", "around the clock"],
79:     [r"\bMt\.?(?=\s+[A-Z])", "Mount"],
80:     [r"\bMr\.(?=\s)", "Mister"],
81:     [r"\bProf\.(?=\s)", "Professor"],
82:     [r"\bNo\.\s*(?=\d)", "number "],
83:     [r"\bSte\.?\s*(?=\d)", "Suite "],
84:     [r"\bRte\.?(?=\s+\d)", "Route"]
85: ];
86: 
87: def _ordinal(n: int) -> str {
88:     if 11 <= n % 100 <= 13 {
89:         return f"{n}th";
90:     }
91:     return f"{n}" + {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th");
92: }
93: 
94: """Spoken date: "Tuesday, September 29th" (year only when it is not this year)."""
95: def _spoken_date(y: int, m: int, d: int, today: date) -> str {
96:     try {
97:         dt = date(y, m, d);
98:     } except ValueError {
99:         return f"{MONTH_NAMES[m - 1]} {_ordinal(d)}";
100:     }
101:     out = f"{WEEKDAYS[dt.weekday()]}, {MONTH_NAMES[m - 1]} {_ordinal(d)}";
102:     if y != today.year {
103:         out += f", {y}";
104:     }
105:     return out;
106: }
107: 
108: """Year for a month/day with no year: the one closest to today."""
109: def _nearest_year(m: int, d: int, today: date) -> int {
110:     best = today.year;
111:     best_gap = 9999;
112:     for y in [today.year - 1, today.year, today.year + 1] {
113:         try {
114:             gap = abs((date(y, m, d) - today).days);
115:         } except ValueError {
116:             continue;
117:         }
118:         if gap < best_gap {
119:             best = y;
120:             best_gap = gap;
121:         }
122:     }
123:     return best;
124: }
