126: """Is the word right before position `end` a street name (so St/Dr mean Street/Drive)?"""
127: def _street_before(text: str, end: int) -> bool {
128:     m = re.search(r"(\S+)\s+$", text[:end]);
129:     if m is None {
130:         return False;
131:     }
132:     prev = m.group(1);
133:     if re.search(r"[,.;:!?)\]]$", prev) {
134:         return False;
135:     }
136:     if re.fullmatch(r"\d+(st|nd|rd|th)?", prev) {
137:         return True;
138:     }
139:     return bool(re.fullmatch(r"[A-Z][\w'’.-]*", prev)) and prev.lower() not in NOT_STREET;
140: }
141: 
142: """Keep an abbreviation's period only when it also ends the sentence."""
143: def _tail_dot(dot: str, after: str) -> str {
144:     if not dot {
145:         return "";
146:     }
147:     if after.strip() == "" or re.match(r"\s+[A-Z]", after) {
148:         return ".";
149:     }
150:     return "";
151: }
152: 
153: def _road_sub(m: re.Match[str]) -> str {
154:     word = m.group(1);
155:     dot = m.group(2);
156:     text = m.string;
157:     after = text[m.end():];
158:     street = _street_before(text, m.start());
159:     next_cap = re.match(r"\s+[A-Z]", after) is not None;
160:     full = "";
161:     if word == "St" {
162:         full = "Street" if street or not next_cap else "Saint";
163:     } elif word == "Dr" {
164:         full = "Drive" if street or not next_cap else "Doctor";
165:     } elif word in ROAD_ALWAYS {
166:         full = ROAD_ALWAYS[word];
167:     } elif street {
168:         full = ROAD_AFTER_NAME[word];
169:     } else {
170:         return m.group(0);
171:     }
172:     if full == "Saint" or full == "Doctor" {
173:         return full;
174:     }
175:     return full + _tail_dot(dot, after);
176: }
177: 
178: def _day_sub(m: re.Match[str]) -> str {
179:     return DAY_ABBR[m.group(1)] + _tail_dot(m.group(2), m.string[m.end():]);
180: }
181: 
182: def _dir_sub(m: re.Match[str]) -> str {
183:     return DIRECTIONS[m.group(1)];
184: }
185: 
186: def _time_sub(m: re.Match[str]) -> str {
187:     h = int(m.group(1));
188:     mm = m.group(2) or "00";
189:     ap = m.group(3).lower();
190:     if h > 12 or int(mm) > 59 {
191:         return m.group(0);
192:     }
193:     if h == 12 and mm == "00" {
194:         return "noon" if ap == "p" else "midnight";
195:     }
196:     clock = str(h) if mm == "00" else f"{h}:{mm}";
197:     return clock + (" p.m." if ap == "p" else " a.m.");
198: }
