200: """Spoken form of a 24-hour clock time: 22:00 -> "10 p.m.", 19:30 -> "7:30 p.m.",
201: 09:05 -> "9:05 a.m.", 12:00 -> "noon", 00:00 -> "midnight"."""
202: def _spoken_24h(h: int, mm: str) -> str {
203:     if mm == "00" and h == 12 {
204:         return "noon";
205:     }
206:     if mm == "00" and h == 0 {
207:         return "midnight";
208:     }
209:     h12 = h % 12 or 12;
210:     clock = str(h12) if mm == "00" else f"{h12}:{mm}";
211:     return clock + (" p.m." if h >= 12 else " a.m.");
212: }
213: 
214: """24-hour times that can't be 12-hour ones: hour 13-23 or 0, a leading zero
215: ("09:00") or seconds ("20:00:00"). Bare "10:30" stays as written."""
216: def _clock24_sub(m: re.Match[str]) -> str {
217:     hh = m.group(1);
218:     h = int(hh);
219:     mm = m.group(2);
220:     if h > 23 or int(mm) > 59 {
221:         return m.group(0);
222:     }
223:     if h >= 13 or h == 0 or (len(hh) == 2 and hh.startswith("0")) or m.group(3) {
224:         return _spoken_24h(h, mm);
225:     }
226:     return m.group(0);
227: }
228: 
229: def _money_sub(m: re.Match[str]) -> str {
230:     dollars = int(m.group(1).replace(",", ""));
231:     cents = int(m.group(2)) if m.group(2) else 0;
232:     out = f"{dollars} dollar" + ("" if dollars == 1 else "s");
233:     if cents > 0 {
234:         out += f" and {cents} cent" + ("" if cents == 1 else "s");
235:     }
236:     return out;
237: }
238: 
239: def _distance_sub(m: re.Match[str]) -> str {
240:     num: str = m.group(1);
241:     if num.endswith(".0") {
242:         num = num[:-2];
243:     }
244:     unit: str = {"mi": "mile", "min": "minute", "mins": "minute", "hr": "hour", "hrs": "hour", "ft": "foot"}[m.group(2)];
245:     if num != "1" {
246:         unit = "feet" if unit == "foot" else unit + "s";
247:     }
248:     return num + " " + unit;
249: }
