251: """Line-by-line markdown flattening: drop headings, bullets and list numbers;
252: end each line with punctuation so flattened lines stay separate sentences."""
253: def _flatten_lines(text: str) -> str {
254:     out: list[str] = [];
255:     for raw in text.splitlines() {
256:         line: str = raw.strip();
257:         line = re.sub(r"^#{1,6}\s*", "", line);
258:         line = re.sub(r"^>\s?", "", line);
259:         line = re.sub(r"^[-*•+]\s+", "", line);
260:         line = re.sub(r"^\d{1,2}[.)]\s+", "", line);
261:         line = line.strip();
262:         if line {
263:             out.append(line);
264:         }
265:     }
266:     for i in range(len(out) - 1) {
267:         if not re.search(r"[.!?:;,]$", out[i]) {
268:             out[i] = out[i] + ".";
269:         }
270:     }
271:     return " ".join(out);
272: }
