274: """Rewrite `text` so it reads naturally out loud. `today` anchors dates (tests pass it)."""
275: def speakable(text: str, today: date | None = None) -> str {
276:     if not text {
277:         return "";
278:     }
279:     ref = today or date.today();
280:     t: str = str(text);
281: 
282:     # Links, URLs, markdown, emoji.
283:     t = re.sub(r"\[([^\]]+)\]\([^)]*\)", r"\1", t);
284:     t = re.sub(r"https?://\S+", " ", t);
285:     t = re.sub(r"\bwww\.\S+", " ", t);
286:     t = re.sub(r"\b[\w-]+\.(?:com|org|edu|gov|net|io|ai)(?:/\S*)?(?=[\s,;:!?]|\.?$|\.\s)", " ", t);
287:     t = _flatten_lines(t);
288:     t = re.sub(r"\*\*|__|~~|`+", "", t);
289:     t = re.sub(r"(?<!\w)[*_]|[*_](?!\w)", "", t);
290:     t = re.sub(r"[\U0001F000-\U0001FAFF☀-➿⬀-⯿⌀-⏿️‍⃣]", " ", t);
291:     t = t.replace("→", " to ").replace("…", ".").replace("·", ", ").replace("•", ", ");
292: 
293:     # Names and fixed phrases.
294:     for pr in PHRASES {
295:         t = re.sub(pr[0], pr[1], t);
296:     }
297: 
298:     # Symbols.
299:     t = t.replace("&amp;", " and ").replace("&", " and ").replace("@", " at ");
300:     t = re.sub(r"\$(\d[\d,]*)(?:\.(\d{2}))?", _money_sub, t);
301:     t = t.replace("$", "");
302:     t = re.sub(r"(\d)\s*%", r"\1 percent", t);
303:     t = re.sub(r"#(?=\d)", "number ", t);
304:     t = re.sub(r"(\d)\+", r"\1 plus", t);
305:     t = t.replace("+", " plus ");
306:     t = re.sub(r"\b(\d+(?:\.\d+)?)\s?(mi|mins|min|hrs|hr|ft)\b\.?", _distance_sub, t);
307: 
308:     # Dates (before "/" and "-" are touched). ISO date-times first:
309:     # "2026-10-10 19:30:00" -> "Saturday, October 10th at 7:30 p.m.".
310:     t = re.sub(
311:         r"\b(\d{4})-(\d{2})-(\d{2})[T ](\d{1,2}):(\d{2})(?::\d{2}(?:\.\d+)?)?(?:[+-]\d{2}:?\d{2}|Z)?\b",
312:         lambda (m: re.Match[str]) -> str {
313:             h = int(m.group(4));
314:             if h > 23 or int(m.group(5)) > 59 {
315:                 return _spoken_date(int(m.group(1)), int(m.group(2)), int(m.group(3)), ref);
316:             }
317:             return _spoken_date(int(m.group(1)), int(m.group(2)), int(m.group(3)), ref) + " at " + _spoken_24h(h, m.group(5));
318:         },
319:         t
320:     );
321:     t = re.sub(
322:         r"\b(\d{4})-(\d{2})-(\d{2})\b",
323:         lambda (m: re.Match[str]) -> str { return _spoken_date(int(m.group(1)), int(m.group(2)), int(m.group(3)), ref); },
324:         t
325:     );
326:     t = re.sub(
327:         r"(?<![\d/])(1[0-2]|0?[1-9])/(3[01]|[12]\d|0?[1-9])(?:/(\d{4}|\d{2}))?(?![\d/])",
328:         lambda (m: re.Match[str]) -> str {
329:             mo = int(m.group(1));
330:             d = int(m.group(2));
331:             y = _nearest_year(mo, d, ref);
332:             if m.group(3) {
333:                 y = int(m.group(3)) if len(m.group(3)) == 4 else 2000 + int(m.group(3));
334:             }
335:             return _spoken_date(y, mo, d, ref);
336:         },
337:         t
338:     );
339:     t = re.sub(
340:         r"(?<![\w'’-])(Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sept|Sep|Oct|Nov|Dec)\.?(?=\s+\d)",
341:         lambda (m: re.Match[str]) -> str { return MONTH_ABBR[m.group(1)]; },
342:         t
343:     );
344:     t = re.sub(
345:         r"(?<![\w'’])(Mon|Tues|Tue|Wed|Thurs|Thur|Thu|Fri|Sat|Sun)(\.?)(?![\w'’])",
346:         _day_sub,
347:         t
348:     );
349:     month_alt = "|".join(MONTH_NAMES);
350:     day_alt = "|".join(WEEKDAYS);
351:     t = re.sub(
352:         r"(?:\b(" + day_alt + r"),?\s+)?\b(" + month_alt + r")\s+(\d{1,2})(?:st|nd|rd|th)?\b(?![:\d])(?:,?\s+(\d{4})\b)?",
353:         lambda (m: re.Match[str]) -> str {
354:             mo = MONTH_NAMES.index(m.group(2)) + 1;
355:             d = int(m.group(3));
356:             y = int(m.group(4)) if m.group(4) else _nearest_year(mo, d, ref);
357:             return _spoken_date(y, mo, d, ref);
358:         },
359:         t
360:     );
361: 
362:     # Times: 7:00 PM -> 7 p.m.; 12 PM -> noon; ranges and "Monday 7 p.m." -> "Monday at 7 p.m.".
363:     t = re.sub(r"\b(\d{1,2})(?::(\d{2}))?\s*([AaPp])\.?\s*[Mm]\b\.?", _time_sub, t);
364:     t = re.sub(r"(?<![\d:])(\d{1,2}):(\d{2})(?::(\d{2}))?(?![\d:])(?!\s*[AaPp]\.?\s*[Mm]\b)", _clock24_sub, t);
365:     t = re.sub(r"(\d)\s*[-–—]\s*(\d{1,2}(?::\d{2})? [ap]\.m\.)", r"\1 to \2", t);
366:     t = re.sub(r"(\d [ap]\.m\.)\s*[-–—]\s*(\d)", r"\1 to \2", t);
367:     t = re.sub(r"\b(" + day_alt + r")\s*[-–—]\s*(" + day_alt + r")\b", r"\1 to \2", t);
368:     t = re.sub(r"\b(" + day_alt + r") (\d{1,2}(?::\d{2})? [ap]\.m\.|noon|midnight)", r"\1 at \2", t);
369:     # "October 10th 7 p.m." / "October 2nd, 9:30 p.m." -> "October 10th at 7 p.m.".
370:     t = re.sub(r"(\d(?:st|nd|rd|th))\s*,?\s+(\d{1,2}(?::\d{2})? [ap]\.m\.|noon|midnight)", r"\1 at \2", t);
371: 
372:     # Directions, then road suffixes (Street/Saint, Drive/Doctor).
373:     t = re.sub(r"(?<![\w'’.-])(NE|NW|SE|SW|N|S|E|W)\.?(?=\s+(?:[A-Z]|\d))", _dir_sub, t);
374:     road_alt = "|".join(["St", "Dr"] + list(ROAD_ALWAYS.keys()) + list(ROAD_AFTER_NAME.keys()));
375:     t = re.sub(r"(?<![\w'’-])(" + road_alt + r")(\.?)(?![\w'’])", _road_sub, t);
376: 
377:     # Parentheses and leftover symbols become pauses or disappear.
378:     t = re.sub(r"[(\[{]", ", ", t);
379:     t = re.sub(r"[)\]}]", ", ", t);
380:     t = t.replace("—", ", ").replace("–", ", ");
381:     t = re.sub(r"(\w)/(\w)", r"\1 or \2", t);
382:     t = re.sub(r"[<>|^=~*_#\\/]", " ", t);
383:     t = t.replace("\"", "").replace("“", "").replace("”", "");
384: 
385:     # Whitespace and punctuation tidy-up.
386:     t = re.sub(r"\s+", " ", t);
387:     t = re.sub(r"\s+([,.;:!?])", r"\1", t);
388:     for _ in range(3) {
389:         t = re.sub(r",\s*,", ",", t);
390:         t = re.sub(r",\s*([.;:!?])", r"\1", t);
391:         t = re.sub(r"([;:!?])\s*,", r"\1", t);
392:         t = re.sub(r"(?<![ap]\.m)\.\s*,", ".", t);
393:         t = re.sub(r":\s*\.", ".", t);
394:     }
395:     t = re.sub(r"\.{2,}", ".", t);
396:     t = re.sub(r"([,;:!?])(?=[A-Za-z])", r"\1 ", t);
397:     t = re.sub(r"\s+", " ", t);
398:     return t.strip(" ,;:");
399: }
