1: """Template fallback that sounds like a friend who knows Ann Arbor talking you
2: through the week, not a numbered list.
3: 
4: Structure: greeting and one line that sets up the week; then grouped sections
5: (getting around, things worth your time, civic), each skipped when empty; the
6: strongest reason woven into each sentence with rotating phrasings so no reason
7: phrase repeats; one naturally worded action per item, varied by kind; human
8: times ("Friday evening at eight"); a short warm closing. Aims for 130-180
9: spoken words. Returns speakable text.
10: """
11: 
12: import re;
13: import from datetime { date }
14: import from services.speakable { speakable, word_count }
15: 
16: glob MIN_WORDS: int = 130;
17: glob MAX_WORDS: int = 178;
18: 
19: glob DAY_NAMES: dict[str, str] = {
20:     "mon": "Monday", "tue": "Tuesday", "wed": "Wednesday", "thu": "Thursday",
21:     "fri": "Friday", "sat": "Saturday", "sun": "Sunday"
22: };
23: glob HOUR_WORDS: list[str] = [
24:     "twelve", "one", "two", "three", "four", "five", "six", "seven", "eight",
25:     "nine", "ten", "eleven", "twelve"
26: ];
27: glob MINUTE_WORDS: dict[int, str] = {15: "fifteen", 30: "thirty", 45: "forty-five"};
28: 
29: # Reason text from the relevance agent -> spoken phrasings. Each pattern rotates
30: # through its variants so the same phrase is never used twice in one brief.
31: glob REASON_PATTERNS: list[list[any]] = [
32:     ["home", r"Near your home in (.+)", ["close to home in {0}", "near your place in {0}", "just by your home in {0}"]],
33:     ["route", r"On your (\w+) route via (.+)", ["right on your {0} route through {1}", "along your {0} route via {1}", "in the way of your {0} ride through {1}"]],
34:     ["area", r"Affects (.+), where you live or travel", ["and it touches {0}, your part of town", "and it affects {0}, where you get around", "and it lands in {0}, close to you"]],
35:     ["near", r"Close by at (.+)", ["just around the corner at {0}", "a short trip to {0}", "close by at {0}"]],
36:     ["interest", r"Matches your interest in (.+)", ["since you're into {0}", "right up your alley if you like {0}", "a good pick for your {0} side"]],
37:     ["follow", r"From (.+), which you follow", ["since you follow {0}", "from {0}, who you follow", "hosted by {0}, one of your follows"]]
38: ];
