70: def _part_of_day(h24: int) -> str {
71:     if h24 < 12 {
72:         return "morning";
73:     }
74:     if h24 < 17 {
75:         return "afternoon";
76:     }
77:     if h24 < 21 {
78:         return "evening";
79:     }
80:     return "night";
81: }
