83: def _clock(h24: int, minute: int) -> str {
84:     if h24 == 12 and minute == 0 {
85:         return "noon";
86:     }
87:     words = HOUR_WORDS[h24 % 12];
88:     if minute == 0 {
89:         return words;
90:     }
91:     return words + " " + MINUTE_WORDS.get(minute, f"{minute:02d}");
92: }
