132: """The strongest reason that still has an unused phrasing, spoken; "" if none."""
133: def _reason(reasons: list[str], used: dict[str, int], offset: int = 0) -> str {
134:     found = 0;
135:     for r in reasons {
136:         text = str(r).strip().rstrip(".");
137:         for pat in REASON_PATTERNS {
138:             m: any = re.fullmatch(pat[1], text);
139:             if m is None {
140:                 continue;
141:             }
142:             n = used.get(pat[0], 0);
143:             if n >= len(pat[2]) {
144:                 break;
145:             }
146:             if found < offset {
147:                 found += 1;
148:                 break;
149:             }
150:             used[pat[0]] = n + 1;
151:             phrase = pat[2][n].format(*m.groups());
152:             return re.sub(r"\bin ((?:[\w'.-]+ )*(?:Street|St|Avenue|Ave|Road|Rd|corridor))$", r"on \1", phrase);
153:         }
154:     }
155:     return "";
156: }
