158: """The imperative part of a to-do: "Stops may move (All week). Check The Ride alerts
159: and allow 10 extra minutes." -> "check The Ride alerts and allow 10 extra minutes"."""
160: def _imperative(action: str, when: str = "") -> str {
161:     sentences = [s.strip() for s in re.split(r"(?<=[.!?])\s+", action.strip()) if s.strip()];
162:     verbs = r"(?i)^(check|leave|plan|shift|sign|save|rsvp|allow|give|take|use|avoid|expect|email|comment)\b";
163:     pick: str = sentences[-1] if sentences else "";
164:     for s in sentences {
165:         if re.match(verbs, s) {
166:             pick = s;
167:             break;
168:         }
169:     }
170:     pick = pick.rstrip(".");
171:     if when.strip() and when.strip() in pick {
172:         pick = pick.replace(when.strip(), "those hours");
173:     }
174:     if re.match(r"(?i)^plan around it", pick) {
175:         return "plan around it";
176:     }
177:     if re.match(r"(?i)^sign up for public comment", pick) {
178:         return "sign up to comment";
179:     }
180:     return pick[:1].lower() + pick[1:];
181: }
182: 
183: def _price_phrase(action: str, k: int) -> str {
184:     m: any = re.search(r"\$(\d+)", action);
185:     if m is not None {
186:         return PAID_ACTIONS[k % len(PAID_ACTIONS)].format(m.group(1));
187:     }
188:     if re.match(r"(?i)^free\b", action.strip()) {
189:         return FREE_ACTIONS[k % len(FREE_ACTIONS)];
190:     }
191:     return OPEN_ACTIONS[k % len(OPEN_ACTIONS)];
192: }
193: 
194: def _the(name: str) -> str {
195:     n = name.strip();
196:     if n.lower().startswith(("the", "a ")) {
197:         return n;
198:     }
199:     return "the " + n;
200: }
201: 
202: def _opening(n_around: int, n_fun: int, n_civic: int) -> str {
203:     if n_around >= 2 {
204:         return "It's a busy week for getting around, so there's a bit to plan for.";
205:     }
206:     if n_around == 1 {
207:         return "It's a pretty easy week, with one thing to plan around.";
208:     }
209:     if n_fun >= 3 {
210:         return "It's a good week to get out, with a few things worth your time.";
211:     }
212:     return "It's a quiet week, with a couple of things worth knowing about.";
213: }
214: 
215: """'is' before a day or time, 'has a' before a noun phrase like 'comment deadline'."""
216: def _verb_when(when: str) -> str {
217:     first = when.split(" ")[0].rstrip(",") if when else "";
218:     if not first or first in DAY_NAMES.values() or first[:1].isdigit() or first in ["all", "on", "this", "every"] {
219:         return "is " + when;
220:     }
221:     return "has a " + when;
222: }
223: 
224: def _around_sentence(it: dict[str, any], i: int, reason: str, ref: date | None) -> str {
225:     lead = "Heads up on getting around: " if i == 0 else ["Also on the roads, ", "One more for your commute: "][(i - 1) % 2];
226:     subject = _the(str(it["name"]));
227:     if i == 0 {
228:         subject = subject[:1].lower() + subject[1:];
229:     }
230:     when = natural_when(str(it.get("when", "")), ref);
231:     out = f"{lead}{subject} runs {when}" if when else f"{lead}{subject} is in place";
232:     if reason {
233:         out += f", {reason}";
234:     }
235:     act = _imperative(str(it.get("action", "")), str(it.get("when", "")));
236:     if act {
237:         out += f", so {act}";
238:     }
239:     return out + ".";
240: }
241: 
242: def _fun_sentence(it: dict[str, any], i: int, prev_day: int, used_leads: list[str], reason: str, ref: date | None) -> str {
243:     day = int(it.get("day", 0) or 0);
244:     if i == 0 {
245:         lead = FUN_LEADS_FIRST[0];
246:     } elif day >= 5 and prev_day < 5 and "weekend" not in used_leads {
247:         lead = "Over the weekend, ";
248:         used_leads.append("weekend");
249:     } elif day > prev_day and "later" not in used_leads {
250:         lead = "Later in the week, ";
251:         used_leads.append("later");
252:     } else {
253:         options = ["If you want more, ", "Also worth a look, ", "And "];
254:         lead = options[len(used_leads) % len(options)];
255:         used_leads.append(lead);
256:     }
257:     when = natural_when(str(it.get("when", "")), ref);
258:     out = f"{lead}{it['name']} {_verb_when(when)}" if when else f"{lead}there's {it['name']}";
259:     if reason {
260:         out += f", {reason}";
261:     }
262:     out += ", " + _price_phrase(str(it.get("action", "")), i);
263:     return out + ".";
264: }
265: 
266: def _civic_sentence(it: dict[str, any], i: int, reason: str, ref: date | None) -> str {
267:     lead = CIVIC_LEADS[i % len(CIVIC_LEADS)];
268:     name = str(it["name"]);
269:     if ": " in name {
270:         (head, rest) = name.split(": ", 1);
271:         name = f"{head} on {rest}";
272:     }
273:     subject = _the(name) if i == 0 else _the(name)[:1].upper() + _the(name)[1:];
274:     when = natural_when(str(it.get("when", "")), ref);
275:     out = f"{lead}{subject} {_verb_when(when)}" if when else f"{lead}{subject} is coming up";
276:     if reason {
277:         out += f", {reason}";
278:     }
279:     act = _imperative(str(it.get("action", "")), str(it.get("when", "")));
280:     if act.startswith("sign up to comment") {
281:         ask = CIVIC_ASKS[i % len(CIVIC_ASKS)];
282:         out += ", " + ask;
283:     } elif act {
284:         out += f", so {act}";
285:     } else {
286:         out += ", " + CIVIC_ASKS[(i + 1) % len(CIVIC_ASKS)];
287:     }
288:     return out + ".";
289: }
290: 
291: def _build(first_name: str, items: list[dict[str, any]], reasons_per_item: dict[int, int], ref: date | None) -> str {
292:     around = [(i, it) for (i, it) in enumerate(items) if _group(str(it["kind"])) == "around"];
293:     fun = sorted([(i, it) for (i, it) in enumerate(items) if _group(str(it["kind"])) == "fun"], key=lambda (p: tuple) -> int { return int(p[1].get("day", 0) or 0); });
294:     civic = [(i, it) for (i, it) in enumerate(items) if _group(str(it["kind"])) == "civic"];
295:     hello = "Good morning." if first_name.strip().lower() in ["", "you"] else f"Good morning, {first_name.strip()}.";
296:     parts: list[str] = [hello, _opening(len(around), len(fun), len(civic))];
297:     used: dict[str, int] = {};
298:     def reason_for(idx: int, it: dict[str, any]) -> str {
299:         n = reasons_per_item.get(idx, 1);
300:         if n <= 0 {
301:             return "";
302:         }
303:         first = _reason(list(it.get("reasons", [])), used);
304:         if n >= 2 and first {
305:             second = _reason(list(it.get("reasons", [])), used, 1);
306:             if second {
307:                 return first + (", and " if not second.startswith("and ") else ", ") + second;
308:             }
309:         }
310:         return first;
311:     }
312:     for (k, pair) in enumerate(around) {
313:         parts.append(_around_sentence(pair[1], k, reason_for(pair[0], pair[1]), ref));
314:     }
315:     prev = -99;
316:     fun_leads: list[str] = [];
317:     for (k, pair) in enumerate(fun) {
318:         parts.append(_fun_sentence(pair[1], k, prev, fun_leads, reason_for(pair[0], pair[1]), ref));
319:         prev = int(pair[1].get("day", 0) or 0);
320:     }
321:     for (k, pair) in enumerate(civic) {
322:         parts.append(_civic_sentence(pair[1], k, reason_for(pair[0], pair[1]), ref));
323:     }
324:     parts.append(CLOSINGS[sum([ord(c) for c in first_name]) % len(CLOSINGS)]);
325:     return speakable(" ".join(parts), ref);
326: }
327: 
328: """The narrative template brief. Starts with one reason per item; adds a second
329: reason where it fits when short, drops reasons from the end when long."""
330: def narrative_brief(first_name: str, items: list[dict[str, any]], ref: date | None = None) -> str {
331:     if len(items) == 0 {
332:         hello = "Good morning." if first_name.strip().lower() in ["", "you"] else f"Good morning, {first_name.strip()}.";
333:         return speakable(f"{hello} It's a quiet week, and nothing in Ann Arbor needs your attention yet. Enjoy the calm.", ref);
334:     }
335:     per: dict[int, int] = {i: 1 for i in range(len(items))};
336:     text = _build(first_name, items, per, ref);
337:     i = 0;
338:     while word_count(text) < MIN_WORDS and i < len(items) {
339:         per[i] = 2;
340:         longer = _build(first_name, items, per, ref);
341:         if word_count(longer) <= MAX_WORDS {
342:             text = longer;
343:         } else {
344:             per[i] = 1;
345:         }
346:         i += 1;
347:     }
348:     j = len(items) - 1;
349:     while word_count(text) > MAX_WORDS and j >= 0 {
350:         per[j] = 0;
351:         text = _build(first_name, items, per, ref);
352:         j -= 1;
353:     }
354:     return text;
355: }

1: """Provider-neutral LLM hookup for A2 Pulse.
2: 
3: The model comes from LLM_MODEL (LiteLLM naming, e.g. gpt-4o-mini,
4: claude-haiku-4-5, gemini/gemini-2.0-flash, ollama/llama3) plus that provider's
5: key. With no model or no key every caller uses its heuristic/template fallback
6: and no LLM code runs at all. When on, each call gets a hard deadline
7: (LLM_TIMEOUT_S) and falls back on timeout or error.
8: 
9: Optional: LLM_API_KEY (one key for any provider) and LLM_API_BASE (an
10: OpenAI-compatible gateway URL, with LLM_MODEL like "openai/<model>").
11: jac.toml passes the same two settings to the ambient `by llm` model.
12: """
13: 
14: import os;
15: import re;
16: import time;
17: import from pathlib { Path }
18: import threading;
19: # Must come before any byLLM import: empty/off LLM_MODEL would otherwise crash it.
20: import from services.llm_env { llm_model_off }
21: import from jaclang.byllm.lib { Model, MTRuntime }
22: 
23: glob LLM_TIMEOUT_S: float = 8.0;
24: 
25: # Provider prefix (LiteLLM "provider/model", or a bare-name family) -> env keys, any one of which unlocks it.
26: glob PROVIDER_KEYS: dict[str, list[str]] = {
27:     "openai": ["OPENAI_API_KEY"],
28:     "anthropic": ["ANTHROPIC_API_KEY"],
29:     "gemini": ["GEMINI_API_KEY", "GOOGLE_API_KEY"],
30:     "vertex_ai": ["GOOGLE_APPLICATION_CREDENTIALS"],
31:     "mistral": ["MISTRAL_API_KEY"],
32:     "groq": ["GROQ_API_KEY"],
33:     "deepseek": ["DEEPSEEK_API_KEY"],
34:     "together_ai": ["TOGETHERAI_API_KEY", "TOGETHER_API_KEY"],
35:     "openrouter": ["OPENROUTER_API_KEY"],
36:     "xai": ["XAI_API_KEY"],
37:     "cohere": ["COHERE_API_KEY"],
38:     "azure": ["AZURE_API_KEY"],
39:     "bedrock": ["AWS_ACCESS_KEY_ID"],
40:     "ollama": [],
41:     "ollama_chat": [],
42:     "local": []
43: };
44: 
45: # Bare model names LiteLLM maps to a provider without a "provider/" prefix.
46: glob BARE_FAMILIES: list[list[str]] = [
47:     ["gpt-", "openai"], ["o1", "openai"], ["o3", "openai"], ["o4", "openai"],
48:     ["chatgpt", "openai"], ["claude", "anthropic"], ["gemini-", "gemini"]
49: ];
50: 
51: """byLLM's Model plus request options it does not pass through on its own,
52: such as reasoning_effort (LiteLLM maps it to each provider's thinking setting)."""
53: obj BriefModel(Model) {
54:     has extra_params: dict[str, any] = {};
55: 
56:     override def make_model_params(mt_run: MTRuntime) -> dict {
57:         params: dict = super.make_model_params(mt_run);
58:         for (k, v) in self.extra_params.items() {
59:             params[k] = v;
60:         }
61:         return params;
62:     }
63: }
64: 
65: """Reasoning level to request. LLM_REASONING_EFFORT wins (off or default = send
66: nothing); otherwise Gemini gets "minimal", the lowest LiteLLM can express, and
67: other providers get nothing."""
68: def reasoning_effort_for(provider: str) -> str {
69:     v = os.environ.get("LLM_REASONING_EFFORT", "").strip().lower();
70:     if v in ["off", "default"] {
71:         return "";
72:     }
73:     if v {
74:         return v;
75:     }
76:     return "minimal" if provider in ["gemini", "vertex_ai"] else "";
77: }
78: 
79: glob _llm_status: dict[str, any] = {},
80:      brief_llm: any = None;
81: 
82: """Read the project .env into os.environ without overriding anything already set.
83: `jac run` / `jac test` do not load .env on their own."""
84: def _load_dotenv {
85:     here = Path(str(__file__ or ".")).resolve().parent.parent / ".env";
86:     for path in [here, Path.cwd() / ".env"] {
87:         if not path.is_file() {
88:             continue;
89:         }
90:         try {
91:             for line in path.read_text().splitlines() {
92:                 s = line.strip();
93:                 if not s or s.startswith("#") or "=" not in s {
94:                     continue;
95:                 }
96:                 (k, v) = s.split("=", 1);
97:                 k = k.strip().removeprefix("export ").strip();
98:                 v = v.strip().strip('"').strip("'");
99:                 if k and k not in os.environ {
100:                     os.environ[k] = v;
101:                 } elif k and not str(os.environ.get(k, "")).strip() and v {
102:                     # Empty shell exports (LLM_MODEL=) must not block .env values.
103:                     os.environ[k] = v;
104:                 }
105:             }
106:         } except Exception {
107:             continue;
108:         }
109:         return;
110:     }
111: }
112: 
113: """Which provider a LiteLLM model name routes to ("" when unknown)."""
114: def llm_provider(model: str) -> str {
115:     m = model.strip().lower();
116:     if "/" in m {
117:         return m.split("/", 1)[0];
118:     }
119:     if m.startswith("local:") {
120:         return "local";
121:     }
122:     for fam in BARE_FAMILIES {
123:         if m.startswith(fam[0]) {
124:             return fam[1];
125:         }
126:     }
127:     return "";
128: }
129: 
130: """Decide once whether the LLM is on. LLM_API_KEY is a generic override for any provider."""
131: def _resolve_status -> dict[str, any] {
132:     raw = os.environ.get("LLM_MODEL");
133:     model = (raw or "").strip();
134:     if raw is None or model == "" {
135:         return {"on": False, "model": "", "provider": "", "reason": "LLM_MODEL is not set"};
136:     }
137:     if llm_model_off(model) {
138:         return {"on": False, "model": "", "provider": "", "reason": "LLM_MODEL is off"};
139:     }
140:     provider = llm_provider(model);
141:     generic = os.environ.get("LLM_API_KEY", "").strip();
142:     if generic {
143:         return {"on": True, "model": model, "provider": provider or "custom", "reason": "", "api_key_env": "LLM_API_KEY"};
144:     }
145:     if os.environ.get("LLM_API_BASE", "").strip() {
146:         return {"on": False, "model": model, "provider": provider, "reason": "LLM_API_BASE is set but LLM_API_KEY is not"};
147:     }
148:     if provider not in PROVIDER_KEYS {
149:         return {"on": False, "model": model, "provider": provider, "reason": "unknown provider for " + model + "; set LLM_API_KEY"};
150:     }
151:     keys = PROVIDER_KEYS[provider];
152:     if len(keys) == 0 {
153:         return {"on": True, "model": model, "provider": provider, "reason": ""};
154:     }
155:     for k in keys {
156:         if len(os.environ.get(k, "").strip()) > 8 {
157:             return {"on": True, "model": model, "provider": provider, "reason": ""};
158:         }
159:     }
160:     return {"on": False, "model": model, "provider": provider, "reason": " or ".join(keys) + " is not set"};
161: }
162: 
163: """Pick the concrete API key for BriefModel. Prefer LLM_API_KEY, then the
164: provider's named env vars. Never pass an empty api_key — that can block
165: LiteLLM from reading GEMINI_API_KEY / GOOGLE_API_KEY."""
166: def _resolve_api_key(provider: str) -> str {
167:     generic = os.environ.get("LLM_API_KEY", "").strip();
168:     if generic {
169:         return generic;
170:     }
171:     for k in PROVIDER_KEYS.get(provider, []) {
172:         v = os.environ.get(k, "").strip();
173:         if len(v) > 8 {
174:             return v;
175:         }
176:     }
177:     return "";
178: }
179: 
180: def _configure {
181:     _load_dotenv();
182:     # Jac byLLM / LiteLLM auth Gemini via GOOGLE_API_KEY; we accept GEMINI_API_KEY too.
183:     gem = os.environ.get("GEMINI_API_KEY", "").strip();
184:     goog = os.environ.get("GOOGLE_API_KEY", "").strip();
185:     if gem and not goog {
186:         os.environ["GOOGLE_API_KEY"] = gem;
187:     } elif goog and not gem {
188:         os.environ["GEMINI_API_KEY"] = goog;
189:     }
190:     _llm_status = _resolve_status();
191:     brief_llm = None;
192:     if _llm_status["on"] {
193:         base = os.environ.get("LLM_API_BASE", "").strip();
194:         effort = reasoning_effort_for(str(_llm_status["provider"]));
195:         _llm_status["reasoning_effort"] = effort;
196:         key = _resolve_api_key(str(_llm_status.get("provider", "")));
197:         cfg: dict = ({"base_url": base} if base else {});
198:         extra: dict = ({"reasoning_effort": effort} if effort else {});
199:         if key {
200:             brief_llm = BriefModel(
201:                 model_name=_llm_status["model"], api_key=key,
202:                 config=cfg, extra_params=extra
203:             );
204:         } else {
205:             brief_llm = BriefModel(
206:                 model_name=_llm_status["model"],
207:                 config=cfg, extra_params=extra
208:             );
209:         }
210:         try {
211:             import litellm;
212:             # Bound the provider request itself too, so timed-out worker threads die soon after the deadline.
213:             litellm.request_timeout = LLM_TIMEOUT_S + 2.0;
214:             litellm.num_retries = 0;
215:         } except Exception {
216:         }
217:         via = " via LLM_API_BASE" if os.environ.get("LLM_API_BASE", "").strip() else "";
218:         think = f", reasoning {effort}" if effort else "";
219:         print(f"LLM: {_llm_status['model']} ({_llm_status['provider']}){via}{think}, {int(LLM_TIMEOUT_S)}s timeout");
220:     } else {
221:         print(f"LLM: off, using fallbacks ({_llm_status['reason']})");
222:     }
223: }
224: 
225: """True when an LLM is configured with a key. Cheap: no network, no imports."""
226: def llm_enabled -> bool {
227:     return bool(_llm_status.get("on", False)) and brief_llm is not None;
228: }
229: 
230: """Model name for traces and the UI ("" when off)."""
231: def llm_model_label -> str {
232:     return str(_llm_status.get("model", "")) if llm_enabled() else "";
233: }
234: 
235: def llm_config_status -> dict[str, any] {
236:     return dict(_llm_status);
237: }
238: 
239: """Swap the model (tests inject MockLLM here). None turns the LLM off."""
240: def set_llm(model: any, label: str = "") {
241:     brief_llm = model;
242:     _llm_status = {
243:         "on": model is not None,
244:         "model": label or (str(model.model_name) if model is not None else ""),
245:         "provider": "test",
246:         "reason": "" if model is not None else "disabled"
247:     };
248: }
249: 
250: """Run fn(*args) with a hard deadline. Never raises.
251: Returns {"ok", "value", "error", "ms"}. The call runs on a daemon thread, so a
252: provider that hangs past the deadline is abandoned and never blocks shutdown."""
253: def call_with_deadline(fn: any, args: list[any], seconds: float = LLM_TIMEOUT_S) -> dict[str, any] {
254:     box: dict[str, any] = {"value": None, "error": ""};
255:     def work {
256:         try {
257:             box["value"] = fn(*args);
258:         } except Exception as e {
259:             # Provider errors can echo a masked key; scrub before it reaches traces or logs.
260:             box["error"] = _redact(f"{type(e).__name__}: {str(e)}");
261:         }
262:     }
263:     t0 = time.perf_counter();
264:     th = threading.Thread(target=work, daemon=True, name="pulse-llm");
265:     th.start();
266:     th.join(timeout=seconds);
267:     ms = round((time.perf_counter() - t0) * 1000, 1);
268:     if th.is_alive() {
269:         return {"ok": False, "value": None, "error": f"timed out after {seconds}s", "ms": ms};
270:     }
271:     if box["error"] {
272:         return {"ok": False, "value": None, "error": box["error"], "ms": ms};
273:     }
274:     return {"ok": True, "value": box["value"], "error": "", "ms": ms};
275: }
276: 
277: # ---------------------------------------------------------------- diagnostics
278: def llm_ping -> str by brief_llm(temperature=0.0, max_tokens=5, max_output_retries=0);
279: sem llm_ping = "Connectivity check. Reply with exactly the word: ok";
280: 
281: """Env var names that can carry an LLM credential (names only are ever reported)."""
282: def _key_env_names -> list[str] {
283:     names: list[str] = ["LLM_API_KEY"];
284:     for keys in PROVIDER_KEYS.values() {
285:         for k in keys {
286:             if k not in names {
287:                 names.append(k);
288:             }
289:         }
290:     }
291:     return names;
292: }
293: 
294: """Scrub anything key-shaped from a provider error before returning it."""
295: def _redact(msg: str) -> str {
296:     out = msg;
297:     for k in _key_env_names() {
298:         v = os.environ.get(k, "").strip();
299:         if len(v) > 8 {
300:             out = out.replace(v, "[redacted]");
301:         }
302:     }
303:     return re.sub(r"(sk-|sk_|AIza|key-|Bearer\s+)[\w\-\*\.]{4,}", "[redacted]", out)[:300];
304: }
305: 
306: """What the running process sees: LLM mode, model, which key names are set
307: (never values), and optionally one tiny test call through the same model and
308: 8s deadline the Editor and Ask box use."""
309: def diagnose(probe: bool = True) -> dict[str, any] {
310:     ambient = "";
311:     try {
312:         import from jaclang.byllm.config_loader { get_byllm_config }
313:         ambient = os.environ.get("BYLLM_DEFAULT_MODEL", "").strip() or str(get_byllm_config().get_model_config().get("default_model", ""));
314:     } except Exception {
315:         ambient = "unknown";
316:     }
317:     st = llm_config_status();
318:     out: dict[str, any] = {
