{"file_path": "/workspace/services/brief_editor.jac", "content": """"Editor stage: turn ranked local items into one spoken weekly brief.

With an LLM configured, the Editor writes the brief from speakable item text
and the result is checked (length, no relative days, no copied style example,
no repeated reason phrase) before it is used. Any failure, timeout or an LLM
that is off falls back to the deterministic narrative template. Every final
string goes through speakable().
"""

import re;
import from datetime { date }
import from services { pulse_llm }
import from services.speakable { speakable, word_count }
import from services.brief_narrative { narrative_brief }
import from services.brief_dates { brief_week_label }

glob MIN_LLM_WORDS: int = 60;
glob MAX_WORDS: int = 180;

# Spoken reason phrasings; any one used twice makes a brief sound canned.
glob REASON_PHRASES: list[str] = [
    "near your home", "close to home", "near your place", "by your home",
    "your part of town", "where you get around", "where you live or travel",
    "close to you", "around the corner", "close by", "since you follow",
    "who you follow", "which you follow", "one of your follows",
    "since you're into", "right up your alley", "matches your interest",
    "your interest in"
];

# Signature phrases of the style example in the Editor prompt.
glob STYLE_MARKERS: list[str] = [r"\bSCOR\b", r"homecoming pregame"];

glob GROUPS: list[list[str]] = [
    ["around", "Getting around:"],
    ["fun", "Worth your time:"],
    ["civic", "Civic:"]
];

def _group(kind: str) -> str {
    if kind == "alert" {
        return "around";
    }
    if kind == "civic" {
        return "civic";
    }
    return "fun";
}

"""Scoring rules attached to an item by the ranker, if any."""
def _rules_of(it: dict[str, any]) -> list[dict[str, any]] {
    for key in ["rules", "breakdown", "score_breakdown"] {
        val = it.get(key);
        if isinstance(val, list) {
            return val;
        }
    }
    return [];
}

"""Reasons sorted by rule points, strongest first. A rule detail that was
counted twice counts once; reasons with no rule keep their order at the end."""
def strongest_first(reasons: list[str], rules: list[dict[str, any]] | None = None) -> list[str] {
    points: dict[str, float] = {};
    for r in (rules or []) {
        detail = str(r.get("detail", "")).strip();
        if detail {
            points[detail] = max(points.get(detail, 0.0), float(r.get("points", 0) or 0));
        }
    }
    return sorted(
        [str(r) for r in reasons],
        key=lambda (r: str) -> float { return -points.get(r.strip(), 0.0); }
    );
}

def _with_ordered_reasons(items: list[dict[str, any]]) -> list[dict[str, any]] {
    return [
        {**it, "reasons": strongest_first([str(r) for r in it.get("reasons", [])], _rules_of(it))}
        for it in items
    ];
}

"""Items as the Editor sees them: grouped (getting around, worth your time,
civic), numbered, and already speakable so nothing is left to guess."""
def editor_items_text(items: list[dict[str, any]], today: date | None = None) -> str {
    ref = today or date.today();
    ordered = _with_ordered_reasons(items);
    lines: list[str] = [];
    n = 0;
    for g in GROUPS {
        members = [it for it in ordered if _group(str(it.get("kind", ""))) == g[0]];
        if len(members) == 0 {
            continue;
        }
        if lines {
            lines.append("");
        }
        lines.append(g[1]);
        for it in members {
            n += 1;
            name = speakable(str(it.get("name", "")), ref);
            lines.append(f"{n}. {name}");
            when = speakable(str(it.get("when", "")), ref);
            if when {
                lines.append(f"   When: {when}");
            }
            why = [speakable(r, ref) for r in it["reasons"] if r.strip()];
            if why {
                lines.append("   Why: " + "; ".join(why));
            }
            act = speakable(str(it.get("action", "")), ref);
            if act {
                lines.append(f"   To do: {act}");
            }
        }
    }
    if len(lines) == 0 {
        return "No items this week.";
    }
    return "\n".join(lines);
}

"""The first reason phrasing used more than once in the text, or empty."""
def repeated_reason(text: str) -> str {
    low = text.lower();
    for phrase in REASON_PHRASES {
        if len(re.findall(r"\b" + re.escape(phrase) + r"\b", low)) >= 2 {
            return phrase;
        }
    }
    return "";
}

"""Deterministic narrative brief with each item's reasons strongest first."""
def template_brief(first_name: str, items: list[dict[str, any]], today: date | None = None) -> str {
    ref = today or date.today();
    return speakable(narrative_brief(first_name, _with_ordered_reasons(items), ref), ref);
}

"""Why a spoken LLM brief cannot be used, or empty when it is fine."""
def _llm_problem(spoken: str) -> str {
    n = word_count(spoken);
    if n < MIN_LLM_WORDS {
        return f"LLM brief too short, {n} words";
    }
    if n > MAX_WORDS {
        return f"LLM brief too long, {n} words";
    }
    m = re.search(r"\b(today|tonight|tomorrow)\b", spoken, re.IGNORECASE);
    if m is not None {
        return f"LLM brief says '{m.group(0)}'";
    }
    for marker in STYLE_MARKERS {
        if re.search(marker, spoken, re.IGNORECASE) {
            return "LLM brief copies the style example";
        }
    }
    rep = repeated_reason(spoken);
    if rep {
        return f"LLM brief repeats a reason phrase: '{rep}'";
    }
    return "";
}

"""The Editor prompt: write the spoken brief from the grouped item text."""
def editor_llm_brief(first_name: str, listener: str, week_of: str, items: str) -> str by pulse_llm.brief_llm(temperature=0.5, max_tokens=1200, max_output_retries=0);
sem editor_llm_brief = """You are the Editor of A2 Pulse, a weekly audio brief about Ann Arbor.
Write the brief for the week of week_of, to be read aloud to the listener.
Rules: 130 to 180 words of plain spoken prose, no lists, labels, markdown, emoji or URLs.
Start with "Good morning, first_name." then one line that sets up the week.
Cover the items in their groups: getting around first, then things worth your time, then civic.
Name days by weekday; never say today, tonight or tomorrow.
Weave in each item's strongest reason in your own words and never repeat a reason phrase.
Give one natural action per item and end with a short warm closing.
Use only the facts in items; spell out everything so it reads naturally out loud.
Style example, for tone only and never to be copied: "Good morning Sam. It's a pretty easy week.
Friday night, SCOR has a homecoming pregame at ten, right up your alley. Have a good week.\"""";

"""Build the spoken brief. Returns mode (llm or template), model, the Editor
input, the raw LLM text, the final speakable text, its word count and any
error that caused a fallback."""
def edit_brief(
    first_name: str,
    persona: str,
    items: list[dict[str, any]],
    use_llm: bool = True,
    today: date | None = None
) -> dict[str, any] {
    ref = today or date.today();
    items_text = editor_items_text(items, ref);
    inp: dict[str, any] = {
        "first_name": first_name,
        "listener": speakable(persona, ref),
        "week_of": brief_week_label(ref),
        "items": items_text
    };
    out: dict[str, any] = {
        "mode": "template", "model": "", "input": inp, "raw_llm": None,
        "spoken": "", "words": 0, "error": "", "ms": 0.0
    };
    if not use_llm {
        out["error"] = "LLM not requested";
    } elif not pulse_llm.llm_enabled() {
        out["error"] = "LLM off";
    } else {
        res = pulse_llm.call_with_deadline(
            editor_llm_brief,
            [first_name, inp["listener"], inp["week_of"], items_text]
        );
        out["ms"] = res["ms"];
        if not res["ok"] {
            out["error"] = str(res["error"]);
        } else {
            raw = str(res["value"] or "");
            out["raw_llm"] = raw;
            spoken = speakable(raw, ref);
            problem = _llm_problem(spoken);
            if problem {
                out["error"] = problem;
            } else {
                out["mode"] = "llm";
                out["model"] = pulse_llm.llm_model_label();
                out["spoken"] = spoken;
                out["words"] = word_count(spoken);
                return out;
            }
        }
    }
    spoken = template_brief(first_name, items, ref);
    out["spoken"] = spoken;
    out["words"] = word_count(spoken);
    return out;
}
"}

