1: """Brief week rule: weekends look ahead to next Monday, weekdays use this Monday."""
2: 
3: import from datetime { date, datetime, timedelta }
4: 
5: """Normalize a date or datetime to a plain date."""
6: def _as_date(day: date) -> date {
7:     if isinstance(day, datetime) {
8:         return day.date();
9:     }
10:     return day;
11: }
12: 
13: """The Monday a brief generated on the given day is for: next Monday on Saturday or Sunday, otherwise this week's Monday."""
14: def brief_monday(day: date) -> date {
15:     d = _as_date(day);
16:     wd = d.weekday();
17:     if wd >= 5 {
18:         return d + timedelta(days=7 - wd);
19:     }
20:     return d - timedelta(days=wd);
21: }
22: 
23: """Days from the brief Monday to the given day (negative on the weekend before it)."""
24: def brief_day_index(day: date) -> int {
25:     d = _as_date(day);
26:     return (d - brief_monday(d)).days;
27: }
28: 
29: """Long-form label for the brief Monday, e.g. 'Monday, September 28, 2026'."""
30: def brief_week_label(day: date) -> str {
31:     m = brief_monday(day);
32:     return f"{m.strftime('%A')}, {m.strftime('%B')} {m.day}, {m.year}";
33: }

